import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { Run, Step, StepStatus } from '../types'

const run = atom({ plugin: 'progress', key: 'run' } as const, null)
const nowSeconds = atom({ plugin: 'progress', key: 'nowSeconds' } as const, 0)

/** The widest the bar is drawn; a narrow band gets less. */
const BAR_CELLS = 21
/** What the bar's counter and timer take beside it. */
const GUTTER = 24

// The task list reaches a hook as the tool's own arguments, whose shapes
// differ per tool and, for the app's plan tool, are not in the built-in
// table at all. Read them as plain data and normalise to Step[].
type Loose = Record<string, unknown>

const loose = (value: unknown): Loose =>
  typeof value === 'object' && value !== null ? (value as Loose) : {}

const isStatus = (value: unknown): value is StepStatus =>
  value === 'pending' || value === 'in_progress' || value === 'completed'

const text = (value: unknown): string | undefined =>
  typeof value === 'string' && value.trim() !== '' ? value : undefined

/** Rows of `{ content, status }`: the whole list, in order. */
function listed(value: unknown): Step[] | undefined {
  if (!Array.isArray(value)) return undefined

  const steps: Step[] = []

  for (const row of value) {
    const label = text(loose(row).content)
    if (label === undefined) continue

    const status = loose(row).status
    steps.push({ text: label, status: isStatus(status) ? status : 'pending' })
  }

  return steps.length === 0 ? undefined : steps
}

/** Completes the step under way and starts the next one waiting. */
function advanced(prev: Step[]): Step[] {
  // The list is already a fresh copy, so the found steps are written in place.
  const steps = prev.map(step => ({ ...step }))
  const under = steps.find(step => step.status === 'in_progress')

  if (under !== undefined) under.status = 'completed'

  const next = steps.find(step => step.status === 'pending')

  if (next !== undefined) next.status = 'in_progress'

  return steps
}

/** `done` and `start` name steps by their 1-based place in the list. */
function marked(prev: Step[], done: unknown, start: unknown): Step[] {
  const steps = prev.map(step => ({ ...step }))
  const at = (place: unknown): Step | undefined =>
    typeof place === 'number' && Number.isInteger(place) && place >= 1 && place <= steps.length
      ? steps[place - 1]
      : undefined

  for (const place of Array.isArray(done) ? done : []) {
    const step = at(place)

    if (step !== undefined) step.status = 'completed'
  }

  const started = at(start)

  if (started !== undefined) started.status = 'in_progress'

  return steps
}

const isWhole = (steps: Step[]): boolean =>
  steps.length > 0 && steps.every(step => step.status === 'completed')

function bar(done: number, total: number, cells: number): string {
  const filled = total === 0 ? 0 : Math.round((done / total) * cells)

  return '▓'.repeat(filled) + '░'.repeat(Math.max(0, cells - filled))
}

function elapsed(ms: number): string {
  const seconds = Math.max(0, Math.round(ms / 1000))
  const minutes = Math.floor(seconds / 60)

  if (minutes === 0) return `${seconds}s`
  if (minutes < 60) return `${minutes}m ${seconds % 60}s`

  return `${Math.floor(minutes / 60)}h ${minutes % 60}m`
}

/**
 * Writes the list the change produces, keeping the run's clock across writes,
 * and says once when the last step lands.
 */
async function commit(
  $: EngineInterface,
  change: (prev: Step[]) => Step[],
): Promise<void> {
  const held = await read($, run)
  const live = held !== null && held.finishedAt === null ? held : null
  const prev = live === null ? [] : live.steps
  const steps = change(prev)

  if (steps.length === 0) {
    if (held !== null) await update($, run, () => null)

    return
  }

  const at = await $.clock.now()
  const isDone = isWhole(steps)
  const next: Run = {
    steps,
    startedAt: live === null ? at : live.startedAt,
    finishedAt: isDone ? at : null,
  }

  await update($, run, () => next)
  // The tick only runs while a run is live, so prime the readout here.
  await update($, nowSeconds, () => Math.floor(at / 1000))

  if (!isDone || isWhole(prev)) return

  const count = `${steps.length} step${steps.length === 1 ? '' : 's'}`

  $.ui.toast(`Progress: all ${count} done in ${elapsed(at - next.startedAt)}`)
  // No player outside macOS, and no sound is worth failing a hook over.
  $.audio.play({ asset: 'sounds/done.wav' }).catch(() => undefined)
}

/** Turns the elapsed readout over, one second at a time, while a run is live. */
async function tick($: EngineInterface): Promise<void> {
  try {
    const held = await read($, run)

    if (held === null || held.finishedAt !== null) return

    const second = Math.floor((await $.clock.now()) / 1000)

    // Skip the write when the second has not turned: a write redraws.
    if ((await read($, nowSeconds)) !== second) {
      await update($, nowSeconds, () => second)
    }
  } catch {
    // A tick that cannot read the run has nothing to say.
  }
}

export const register: Register = on => {
  on('tool.call', async ($, e, next) => {
    const answered = await next(e)

    if (answered.deny !== undefined || answered.isError === true) return answered

    // `tool` is compared as a string: the app's plan tool is an MCP tool and
    // is not in the built-in table this module is checked against.
    const tool: string = e.tool
    const args = loose(e)

    if (tool === 'TodoWrite') {
      const steps = listed(args.todos)

      if (steps !== undefined) await commit($, () => steps)
    } else if (tool === 'mcp__ccd_turn__update_plan') {
      const steps = listed(args.items)

      if (steps !== undefined) await commit($, () => steps)
      else if (args.advance === true) await commit($, advanced)
      else if (args.done !== undefined || args.start !== undefined) {
        await commit($, prev => marked(prev, args.done, args.start))
      }
    } else if (tool === 'TaskCreate') {
      const label = text(args.subject)
      const id = text(loose(loose(answered.result).task).id)

      if (label !== undefined) {
        await commit($, prev => [...prev, { text: label, status: 'pending', id }])
      }
    } else if (tool === 'TaskUpdate') {
      const id = text(args.taskId)
      const status = args.status
      const label = text(args.subject)

      if (id !== undefined) {
        await commit($, prev =>
          status === 'deleted'
            ? prev.filter(step => step.id !== id)
            : prev.map(step =>
                step.id !== id
                  ? step
                  : {
                      ...step,
                      text: label ?? step.text,
                      status: isStatus(status) ? status : step.status,
                    },
              ),
        )
      }
    }

    return answered
  }).catch(($, e, next) => next(e))

  // A finished run stays on screen as its own receipt, until the next ask.
  on('prompt.submit', async ($, e, next) => {
    const held = await read($, run)

    if (held !== null && held.finishedAt !== null) await update($, run, () => null)

    return next(e)
  }).catch(($, e, next) => next(e))

  on('session.start', ($, e, next) => {
    $.clock.every(1000, () => {
      void tick($)
    })

    return next(e)
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const held = await read($, run)

    if (e.props.hasSurvey || held === null) return next(e)

    // Read while drawing to subscribe: the tick's write redraws the band.
    const second = await read($, nowSeconds)
    const { Box, Text } = $.ui.resolve(e)

    const total = held.steps.length
    const done = held.steps.filter(step => step.status === 'completed').length
    const isDone = held.finishedAt !== null
    const under = held.steps.find(step => step.status === 'in_progress')
    const ended = held.finishedAt ?? Math.max(second * 1000, held.startedAt)
    const cells = Math.max(8, Math.min(BAR_CELLS, e.props.bodyColumns - GUTTER))
    const label = isDone
      ? `✓ ${total} step${total === 1 ? '' : 's'} done`
      : under?.text

    return (
      <Box flexDirection="column">
        <Box gap={1}>
          <Text color={isDone ? 'success' : 'claude'}>{bar(done, total, cells)}</Text>
          <Text dimColor tabular>
            {done}/{total} · {elapsed(ended - held.startedAt)}
          </Text>
        </Box>
        {label === undefined ? null : (
          <Text color={isDone ? 'success' : 'text'} dimColor={!isDone} wrap="truncate-end">
            {isDone ? '' : '▸ '}
            {label}
          </Text>
        )}
      </Box>
    )
  })
}

