export type StepStatus = 'pending' | 'in_progress' | 'completed'

/** One line of the task list, however the list reached us. */
export type Step = {
  /** The step's label, as the task list carries it. */
  text: string
  status: StepStatus
  /** The task's id, where the list is kept as separate tasks. */
  id?: string
}

/** One task list's life: its steps, when it opened, when it closed. */
export type Run = {
  steps: Step[]
  /** When the list's first write landed, ms since the epoch. */
  startedAt: number
  /** When every step had completed, or null while the run is live. */
  finishedAt: number | null
}

declare module 'claude-code' {
  interface PluginState {
    progress: {
      run: Run | null
      /** Whole seconds since the epoch, bumped by the tick so the elapsed readout redraws. */
      nowSeconds: number
    }
  }
}
